package markdown

import (
	"fmt"
	"strings"
)

// Render translates markdown to HTML.
//
// Refactored from a character-by-character scan into a line-based parser:
// the document is split into lines and each line is rendered independently.
//
//   - "__text__" and "_text_" are rendered as bold and italic
//   - a line starting with "#", "##", ..., "######" is a header
//   - seven or more "#" characters are not a valid header level, so the
//     line is rendered as a paragraph
//   - a line starting with "* " is an unordered list item
//   - anything else is paragraph text
func Render(markdown string) string {
	markdown = renderEmphasis(markdown)

	var html strings.Builder
	inList := false
	listItemOpen := false
	for _, line := range strings.Split(markdown, "\n") {
		if strings.HasPrefix(line, "* ") {
			if !inList {
				inList = true
				html.WriteString("<ul>")
			}
			if listItemOpen {
				html.WriteString("</li>")
			}
			html.WriteString("<li>" + line[2:])
			listItemOpen = true
			continue
		}
		if inList {
			if listItemOpen {
				html.WriteString("</li>")
				listItemOpen = false
			}
			html.WriteString("</ul>")
			inList = false
		}
		html.WriteString(renderLine(line))
	}
	if inList {
		if listItemOpen {
			html.WriteString("</li>")
		}
		html.WriteString("</ul>")
	}
	return html.String()
}

// renderEmphasis converts the first "__" pair to <strong> and the first
// "_" pair to <em>, matching the original implementation, which converted
// only one pair of each across the whole document.
func renderEmphasis(markdown string) string {
	markdown = strings.Replace(markdown, "__", "<strong>", 1)
	markdown = strings.Replace(markdown, "__", "</strong>", 1)
	markdown = strings.Replace(markdown, "_", "<em>", 1)
	return strings.Replace(markdown, "_", "</em>", 1)
}

// renderLine renders a single non-list line as a header or a paragraph.
func renderLine(line string) string {
	if !strings.HasPrefix(line, "#") {
		return "<p>" + line + "</p>"
	}
	level := 0
	for level < len(line) && line[level] == '#' {
		level++
	}
	if level == 7 {
		return "<p>" + line + "</p>"
	}
	// Skip the space after the "#" characters.
	text := line[level:]
	if strings.HasPrefix(text, " ") {
		text = text[1:]
	}
	return fmt.Sprintf("<h%d>%s</h%d>", level, text, level)
}

